-- Alter Hub imported PVP / Misc / Katana Config payload
-- Upload this ENTIRE file as-is and use its RAW URL in the main script.
-- Contains the Fluent compatibility adapter + imported VM.

-- ============================================================================
-- ALTER HUB: RAYFIELD -> FLUENT COMPATIBILITY LAYER
-- Keeps the original V5 VM callbacks untouched while Fluent renders the UI.
-- ============================================================================

local function __AH_InstallFluentCompat(Rayfield)
    if type(Rayfield) ~= "table" then
        return Rayfield
    end

    if Rayfield.__AlterHubFluentInstalled then
        return Rayfield
    end
    Rayfield.__AlterHubFluentInstalled = true

    local env = getgenv and getgenv() or _G
    local __AH_MergeMode = env
        and env.__AH_MergeWindow ~= nil
        and env.__AH_MergeFluent ~= nil

    local Fluent

    if __AH_MergeMode then
        -- MERGE MODE:
        -- Reuse the already-running Alter Hub Fluent library/window.
        Fluent = env.__AH_MergeFluent
    else
        -- Standalone fallback retained for safety.
        if env and env.__AlterHubFluentInstance then
            pcall(function()
                env.__AlterHubFluentInstance:Destroy()
            end)
            env.__AlterHubFluentInstance = nil
        end

        if env and env.Fluent and env.Fluent == env.__AlterHubLastFluent then
            pcall(function()
                env.Fluent:Destroy()
            end)
        end

        Fluent = loadstring(game:HttpGet(
            "https://github.com/dawid-scripts/Fluent/releases/latest/download/main.lua"
        ))()

        if env then
            env.__AlterHubFluentInstance = Fluent
            env.__AlterHubLastFluent = Fluent
        end
    end

    Rayfield.__Fluent = Fluent
    Rayfield.Flags = Rayfield.Flags or {}


    -- Only these tabs are shown in Alter Hub.
    local __AH_AllowedTabs = {
        ["Combat"] = true,
        ["Misc"] = true,
        ["Katana Config"] = true,
        ["Visual"] = true
    }

    local function __AH_CreateDummyControl(settings)
        settings = type(settings) == "table" and settings or {}

        if settings.CurrentValue == nil then
            settings.CurrentValue = false
        end
        if type(settings.CurrentOption) ~= "table" then
            if settings.CurrentOption == nil then
                settings.CurrentOption = {}
            else
                settings.CurrentOption = { settings.CurrentOption }
            end
        end

        function settings:Set(value)
            if self.CurrentOption ~= nil and type(value) == "table" then
                self.CurrentOption = value
            elseif self.CurrentOption ~= nil and type(value) == "string" then
                self.CurrentOption = { value }
            else
                self.CurrentValue = value
            end
        end

        function settings:Refresh(options)
            self.Options = options or {}
        end

        return settings
    end

    local function __AH_CreateDummyTab()
        local DummyTab = {}

        function DummyTab:CreateSection(...)
            local section = {}
            function section:Set(...) end
            return section
        end

        function DummyTab:CreateButton(settings)
            return __AH_CreateDummyControl(settings)
        end

        function DummyTab:CreateToggle(settings)
            local control = __AH_CreateDummyControl(settings)
            if control.Flag ~= nil then
                Rayfield.Flags[control.Flag] = control
            end
            return control
        end

        function DummyTab:CreateSlider(settings)
            local control = __AH_CreateDummyControl(settings)
            if control.Flag ~= nil then
                Rayfield.Flags[control.Flag] = control
            end
            return control
        end

        function DummyTab:CreateDropdown(settings)
            local control = __AH_CreateDummyControl(settings)
            if control.Flag ~= nil then
                Rayfield.Flags[control.Flag] = control
            end
            return control
        end

        function DummyTab:CreateInput(settings)
            local control = __AH_CreateDummyControl(settings)
            if control.Flag ~= nil then
                Rayfield.Flags[control.Flag] = control
            end
            return control
        end

        function DummyTab:CreateColorPicker(settings)
            local control = __AH_CreateDummyControl(settings)
            if control.Flag ~= nil then
                Rayfield.Flags[control.Flag] = control
            end
            return control
        end

        function DummyTab:CreateParagraph(settings)
            return __AH_CreateDummyControl(settings)
        end

        function DummyTab:CreateKeybind(settings)
            local control = __AH_CreateDummyControl(settings)
            if control.Flag ~= nil then
                Rayfield.Flags[control.Flag] = control
            end
            return control
        end

        function DummyTab:CreateLabel(...)
            local label = {}
            function label:Set(...) end
            return label
        end

        function DummyTab:CreateDivider(...)
            local divider = {}
            function divider:Set(...) end
            return divider
        end

        return DummyTab
    end


    local optionCounter = 0

    local function nextId(kind, flag)
        optionCounter = optionCounter + 1
        return "__AH_" .. tostring(kind) .. "_" .. tostring(optionCounter) .. "_" .. tostring(flag or "")
    end

    local function safeCallback(callback, ...)
        if type(callback) == "function" then
            local ok, err = pcall(callback, ...)
            if not ok then
                warn("[Alter Hub / Fluent Adapter] Callback error:", err)
            end
        end
    end

    local function rememberFlag(settings)
        if type(settings) == "table" and settings.Flag ~= nil then
            Rayfield.Flags[settings.Flag] = settings
        end
    end

    local function getParent(tabWrapper)
        return tabWrapper.__CurrentSection or tabWrapper.__FluentTab
    end

    local function decimalPlaces(step)
        if type(step) ~= "number" or step <= 0 then
            return 0
        end
        local text = string.format("%.8f", step)
        text = text:gsub("0+$", "")
        local dot = string.find(text, ".", 1, true)
        if not dot then
            return 0
        end
        return #text - dot
    end

    local function snap(value, step, minValue, maxValue)
        value = tonumber(value) or 0
        if minValue ~= nil then
            value = math.max(value, minValue)
        end
        if maxValue ~= nil then
            value = math.min(value, maxValue)
        end
        if type(step) == "number" and step > 0 then
            value = math.floor((value / step) + 0.5) * step
        end
        return value
    end

    local function normalizeSingleOption(value)
        if type(value) == "table" then
            return value[1]
        end
        return value
    end

    local function dropdownArrayFromFluent(settings, value)
        local result = {}

        if settings.MultipleOptions then
            if type(value) == "table" then
                local options = settings.Options or {}
                for _, option in ipairs(options) do
                    if value[option] then
                        table.insert(result, option)
                    end
                end
            end
        else
            if value ~= nil then
                table.insert(result, value)
            end
        end

        return result
    end

    local function fluentMultiValue(value)
        local result = {}
        if type(value) == "string" then
            result[value] = true
        elseif type(value) == "table" then
            for key, item in pairs(value) do
                if type(key) == "number" then
                    result[item] = true
                elseif item == true then
                    result[key] = true
                end
            end
        end
        return result
    end

    function Rayfield:Notify(data)
        data = type(data) == "table" and data or {}
        return Fluent:Notify({
            Title = tostring(data.Title or "Alter Hub"),
            Content = tostring(data.Content or ""),
            SubContent = data.SubContent and tostring(data.SubContent) or nil,
            Duration = data.Duration or 5
        })
    end

    function Rayfield:Destroy()
        -- Never destroy the host Alter Hub window while merged.
        if __AH_MergeMode then
            return
        end

        pcall(function()
            Fluent:Destroy()
        end)
    end

    -- Rayfield's old configuration loader targets Rayfield controls.
    -- Keep it harmless; the compatibility controls preserve Flags in memory.
    function Rayfield:LoadConfiguration()
        return true
    end

    function Rayfield:CreateWindow(settings)
        settings = type(settings) == "table" and settings or {}

        local title = settings.Name or settings.LoadingTitle or "Alter Hub"
        if tostring(title):find("Quasar", 1, true) then
            title = tostring(title):gsub("Quasar Hub", "Alter Hub")
        end

        local window

        if __AH_MergeMode then
            -- Use the original script's existing window.
            window = env.__AH_MergeWindow
        else
            window = Fluent:CreateWindow({
                Title = tostring(title),
                SubTitle = "Demonfall",
                TabWidth = 160,
                Size = UDim2.fromOffset(620, 520),
                Acrylic = false,
                Theme = "Dark",
                MinimizeKey = Enum.KeyCode.LeftControl
            })
        end

        local WindowWrapper = {
            __FluentWindow = window
        }

        local __AH_TabCreateIndex = 0
        local __AH_AllowedTabIndexes = {
            [1] = true, -- Combat
            [2] = true, -- Misc
            [4] = true  -- Katana Config
        }

        function WindowWrapper:CreateTab(name, image, ext)
            __AH_TabCreateIndex = __AH_TabCreateIndex + 1
            local tabName = tostring(name or "Tab")

            -- Hard-filter by this script's actual tab creation order.
            -- This avoids relying on VM-decrypted tab-name strings.
            if not __AH_AllowedTabIndexes[__AH_TabCreateIndex] then
                return __AH_CreateDummyTab()
            end

            local icon = nil

            -- Fluent expects Lucide icon names. Rayfield commonly uses numeric
            -- asset IDs, so numeric icons are intentionally omitted.
            if type(image) == "string" and image ~= "" and tonumber(image) == nil then
                icon = image
            end

            local fluentTab

            if __AH_MergeMode and env.__AH_MergeTabs then
                -- Map the imported VM tab creation order onto tabs that were
                -- already created in the host window at the requested positions.
                fluentTab = env.__AH_MergeTabs[__AH_TabCreateIndex]

                if not fluentTab then
                    return __AH_CreateDummyTab()
                end
            else
                fluentTab = window:AddTab({
                    Title = tabName,
                    Icon = icon
                })
            end

            local TabWrapper = {
                __FluentTab = fluentTab,
                __CurrentSection = nil
            }

            function TabWrapper:CreateSection(sectionName)
                local section = fluentTab:AddSection(tostring(sectionName or ""))
                self.__CurrentSection = section

                local wrapper = {}

                function wrapper:Set(newName)
                    pcall(function()
                        local root = section.Container and section.Container.Parent
                        if root then
                            local label = root:FindFirstChildOfClass("TextLabel")
                            if label then
                                label.Text = tostring(newName)
                            end
                        end
                    end)
                end

                return wrapper
            end

            function TabWrapper:CreateButton(buttonSettings)
                buttonSettings = type(buttonSettings) == "table" and buttonSettings or {}
                local parent = getParent(self)

                local button = parent:AddButton({
                    Title = tostring(buttonSettings.Name or "Button"),
                    Description = buttonSettings.Description,
                    Callback = function()
                        safeCallback(buttonSettings.Callback)
                    end
                })

                local wrapper = {
                    __Fluent = button
                }

                function wrapper:Set(newButton)
                    pcall(function()
                        if button.SetTitle then
                            button:SetTitle(tostring(newButton))
                        end
                    end)
                end

                return wrapper
            end

            function TabWrapper:CreateToggle(toggleSettings)
                toggleSettings = type(toggleSettings) == "table" and toggleSettings or {}
                toggleSettings.CurrentValue = toggleSettings.CurrentValue == true

                local parent = getParent(self)
                local ready = false

                local toggle = parent:AddToggle(nextId("Toggle", toggleSettings.Flag), {
                    Title = tostring(toggleSettings.Name or "Toggle"),
                    Description = toggleSettings.Description,
                    Default = toggleSettings.CurrentValue,
                    Callback = function(value)
                        if not ready then
                            return
                        end
                        toggleSettings.CurrentValue = value == true
                        safeCallback(toggleSettings.Callback, toggleSettings.CurrentValue)
                    end
                })

                toggleSettings.__Fluent = toggle

                function toggleSettings:Set(value)
                    value = value == true
                    if toggle and toggle.SetValue then
                        toggle:SetValue(value)
                    else
                        toggleSettings.CurrentValue = value
                        safeCallback(toggleSettings.Callback, value)
                    end
                end

                rememberFlag(toggleSettings)
                ready = true
                return toggleSettings
            end

            function TabWrapper:CreateSlider(sliderSettings)
                sliderSettings = type(sliderSettings) == "table" and sliderSettings or {}

                local range = sliderSettings.Range or {0, 100}
                local minValue = tonumber(range[1]) or 0
                local maxValue = tonumber(range[2]) or 100
                local step = tonumber(sliderSettings.Increment) or 1
                local default = tonumber(sliderSettings.CurrentValue) or minValue
                default = snap(default, step, minValue, maxValue)

                sliderSettings.CurrentValue = default

                local parent = getParent(self)
                local ready = false
                local syncing = false
                local slider

                slider = parent:AddSlider(nextId("Slider", sliderSettings.Flag), {
                    Title = tostring(sliderSettings.Name or "Slider"),
                    Description = sliderSettings.Suffix and tostring(sliderSettings.Suffix) or sliderSettings.Description,
                    Default = default,
                    Min = minValue,
                    Max = maxValue,
                    Rounding = decimalPlaces(step),
                    Callback = function(value)
                        if not ready then
                            return
                        end

                        local snapped = snap(value, step, minValue, maxValue)

                        if not syncing and slider and math.abs(snapped - value) > 1e-9 then
                            syncing = true
                            slider:SetValue(snapped)
                            syncing = false
                            return
                        end

                        sliderSettings.CurrentValue = snapped
                        safeCallback(sliderSettings.Callback, snapped)
                    end
                })

                sliderSettings.__Fluent = slider

                function sliderSettings:Set(value)
                    local snapped = snap(value, step, minValue, maxValue)
                    if slider and slider.SetValue then
                        slider:SetValue(snapped)
                    else
                        sliderSettings.CurrentValue = snapped
                        safeCallback(sliderSettings.Callback, snapped)
                    end
                end

                rememberFlag(sliderSettings)
                ready = true
                return sliderSettings
            end

            function TabWrapper:CreateDropdown(dropdownSettings)
                dropdownSettings = type(dropdownSettings) == "table" and dropdownSettings or {}
                dropdownSettings.Options = dropdownSettings.Options or {}

                if type(dropdownSettings.CurrentOption) == "string" then
                    dropdownSettings.CurrentOption = {dropdownSettings.CurrentOption}
                elseif type(dropdownSettings.CurrentOption) ~= "table" then
                    dropdownSettings.CurrentOption = {}
                end

                if not dropdownSettings.MultipleOptions and #dropdownSettings.CurrentOption > 1 then
                    dropdownSettings.CurrentOption = {dropdownSettings.CurrentOption[1]}
                end

                local parent = getParent(self)
                local ready = false
                local dropdown

                local default
                if dropdownSettings.MultipleOptions then
                    default = dropdownSettings.CurrentOption
                else
                    default = dropdownSettings.CurrentOption[1]
                end

                dropdown = parent:AddDropdown(nextId("Dropdown", dropdownSettings.Flag), {
                    Title = tostring(dropdownSettings.Name or "Dropdown"),
                    Description = dropdownSettings.Description,
                    Values = dropdownSettings.Options,
                    Multi = dropdownSettings.MultipleOptions == true,
                    Default = default,
                    Callback = function(value)
                        if not ready then
                            return
                        end

                        local normalized = dropdownArrayFromFluent(dropdownSettings, value)
                        dropdownSettings.CurrentOption = normalized
                        safeCallback(dropdownSettings.Callback, normalized)
                    end
                })

                dropdownSettings.__Fluent = dropdown

                function dropdownSettings:Set(newOption)
                    local normalized

                    if dropdownSettings.MultipleOptions then
                        if type(newOption) == "string" then
                            normalized = {newOption}
                        elseif type(newOption) == "table" then
                            normalized = newOption
                        else
                            normalized = {}
                        end
                        dropdownSettings.CurrentOption = normalized
                        dropdown:SetValue(fluentMultiValue(normalized))
                    else
                        local single = normalizeSingleOption(newOption)
                        normalized = single ~= nil and {single} or {}
                        dropdownSettings.CurrentOption = normalized
                        dropdown:SetValue(single)
                    end
                end

                function dropdownSettings:Refresh(optionsTable)
                    dropdownSettings.Options = optionsTable or {}
                    if dropdown and dropdown.SetValues then
                        dropdown:SetValues(dropdownSettings.Options)
                    end
                end

                rememberFlag(dropdownSettings)
                ready = true
                return dropdownSettings
            end

            function TabWrapper:CreateInput(inputSettings)
                inputSettings = type(inputSettings) == "table" and inputSettings or {}
                inputSettings.CurrentValue = tostring(inputSettings.CurrentValue or "")

                local parent = getParent(self)
                local ready = false

                local input = parent:AddInput(nextId("Input", inputSettings.Flag), {
                    Title = tostring(inputSettings.Name or "Input"),
                    Description = inputSettings.Description,
                    Default = inputSettings.CurrentValue,
                    Placeholder = tostring(inputSettings.PlaceholderText or ""),
                    Numeric = inputSettings.NumbersOnly == true,
                    -- Rayfield fires on FocusLost; Fluent's Finished mode is the
                    -- closest equivalent and avoids callback spam on each keystroke.
                    Finished = true,
                    Callback = function(value)
                        if not ready then
                            return
                        end
                        inputSettings.CurrentValue = tostring(value or "")
                        safeCallback(inputSettings.Callback, inputSettings.CurrentValue)
                    end
                })

                inputSettings.__Fluent = input

                function inputSettings:Set(text)
                    text = tostring(text or "")
                    if input and input.SetValue then
                        input:SetValue(text)
                    else
                        inputSettings.CurrentValue = text
                        safeCallback(inputSettings.Callback, text)
                    end
                end

                rememberFlag(inputSettings)
                ready = true
                return inputSettings
            end

            function TabWrapper:CreateColorPicker(colorSettings)
                colorSettings = type(colorSettings) == "table" and colorSettings or {}
                colorSettings.Color = colorSettings.Color or Color3.fromRGB(255, 255, 255)

                local parent = getParent(self)
                local ready = false

                local picker = parent:AddColorpicker(nextId("Color", colorSettings.Flag), {
                    Title = tostring(colorSettings.Name or "Color"),
                    Description = colorSettings.Description,
                    Default = colorSettings.Color,
                    Callback = function(value)
                        if not ready then
                            return
                        end
                        colorSettings.Color = value
                        safeCallback(colorSettings.Callback, value)
                    end
                })

                colorSettings.__Fluent = picker

                function colorSettings:Set(rgbColor)
                    colorSettings.Color = rgbColor
                    if picker and picker.SetValueRGB then
                        picker:SetValueRGB(rgbColor)
                    else
                        safeCallback(colorSettings.Callback, rgbColor)
                    end
                end

                rememberFlag(colorSettings)
                ready = true
                return colorSettings
            end

            function TabWrapper:CreateParagraph(paragraphSettings)
                paragraphSettings = type(paragraphSettings) == "table" and paragraphSettings or {}

                local parent = getParent(self)
                local paragraph = parent:AddParagraph({
                    Title = tostring(paragraphSettings.Title or ""),
                    Content = tostring(paragraphSettings.Content or "")
                })

                local wrapper = {
                    __Fluent = paragraph
                }

                function wrapper:Set(newSettings)
                    newSettings = type(newSettings) == "table" and newSettings or {}
                    pcall(function()
                        if paragraph.SetTitle and newSettings.Title ~= nil then
                            paragraph:SetTitle(tostring(newSettings.Title))
                        end
                        if paragraph.SetDesc and newSettings.Content ~= nil then
                            paragraph:SetDesc(tostring(newSettings.Content))
                        end
                    end)
                end

                return wrapper
            end

            function TabWrapper:CreateKeybind(keybindSettings)
                keybindSettings = type(keybindSettings) == "table" and keybindSettings or {}
                local current = tostring(keybindSettings.CurrentKeybind or "LeftControl")

                local parent = getParent(self)
                local ready = false

                local keybind = parent:AddKeybind(nextId("Keybind", keybindSettings.Flag), {
                    Title = tostring(keybindSettings.Name or "Keybind"),
                    Description = keybindSettings.Description,
                    Mode = keybindSettings.HoldToInteract and "Hold" or "Toggle",
                    Default = current,
                    Callback = function(value)
                        if not ready or keybindSettings.CallOnChange then
                            return
                        end
                        safeCallback(keybindSettings.Callback, value)
                    end,
                    ChangedCallback = function(newKey)
                        if not ready then
                            return
                        end

                        local name
                        pcall(function()
                            name = newKey.Name
                        end)
                        name = name or tostring(newKey)
                        keybindSettings.CurrentKeybind = name

                        if keybindSettings.CallOnChange then
                            safeCallback(keybindSettings.Callback, name)
                        end
                    end
                })

                keybindSettings.__Fluent = keybind

                function keybindSettings:Set(newKeybind)
                    local name
                    if type(newKeybind) == "string" then
                        name = newKeybind
                    else
                        pcall(function()
                            name = newKeybind.Name
                        end)
                        name = name or tostring(newKeybind)
                    end

                    keybindSettings.CurrentKeybind = name
                    if keybind and keybind.SetValue then
                        keybind:SetValue(name, keybindSettings.HoldToInteract and "Hold" or "Toggle")
                    end

                    if keybindSettings.CallOnChange then
                        safeCallback(keybindSettings.Callback, name)
                    end
                end

                rememberFlag(keybindSettings)
                ready = true
                return keybindSettings
            end

            -- Not used by this V5 UI, but provided for Rayfield compatibility.
            function TabWrapper:CreateLabel(labelText, icon, color, ignoreTheme)
                local parent = getParent(self)
                local paragraph = parent:AddParagraph({
                    Title = tostring(labelText or ""),
                    Content = ""
                })
                local wrapper = {}
                function wrapper:Set(newLabel)
                    pcall(function()
                        if paragraph.SetTitle then
                            paragraph:SetTitle(tostring(newLabel or ""))
                        end
                    end)
                end
                return wrapper
            end

            function TabWrapper:CreateDivider()
                local wrapper = {}
                function wrapper:Set(value)
                    -- Fluent has no direct Rayfield-style divider visibility API.
                end
                return wrapper
            end

            return TabWrapper
        end

        function WindowWrapper:Destroy()
            pcall(function()
                Fluent:Destroy()
            end)
        end

        function WindowWrapper:SelectTab(tab)
            pcall(function()
                window:SelectTab(tab)
            end)
        end

        return WindowWrapper
    end

    return Rayfield
end


